/* @autogenerated */
package net.civeira.phylax.feature.oauth.gdpr.infrastructure.driven;

import java.io.File;
import java.nio.file.Files;
import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.Mockito;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import net.civeira.phylax.common.infrastructure.mail.EmailMessage;
import net.civeira.phylax.common.infrastructure.mail.EmailService;
import net.civeira.phylax.common.infrastructure.mail.MailSent;
import net.civeira.phylax.feature.oauth.consent.infrastructure.driven.ScopesConsentAdapter;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The data portability export (GDPR art. 20) built from the h2 database. */
class UserDataExportAdapterUnitTest {
  private OidcRepositories store;
  private EmailService mail;
  private UserDataExportAdapter export;
  private String tenant;
  private String alice;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    tenant = store.tenant("acme");
    alice = store.user(tenant, "alice", "alice@acme.test");
    store.client(tenant, "web", "Web portal");
    mail = Mockito.mock(EmailService.class);
    export = new UserDataExportAdapter(store.users(), store.consents(), store.dataSource(), mail);
  }

  private JsonNode exported(String user) throws Exception {
    export.requestExport(user, "alice", "alice@acme.test", "acme");
    ArgumentCaptor<EmailMessage> sent = ArgumentCaptor.forClass(EmailMessage.class);
    Mockito.verify(mail).delaySendMessage(sent.capture());
    EmailMessage message = sent.getValue();
    Assertions.assertEquals("alice@acme.test", message.getTargetAddress());
    File file = message.getAttacheds().get(0).getFichero().orElseThrow();
    try {
      return new ObjectMapper().readTree(Files.readString(file.toPath()));
    } finally {
      message.getSentObserver().ifPresent(MailSent::ok);
      Assertions.assertFalse(file.exists(), "The temporary export is removed once sent");
    }
  }

  @Test
  @DisplayName("The export is a valid json with the profile, consents, sessions, terms and audit")
  void full_export() throws Exception {
    new ScopesConsentAdapter(store.users(), store.tenants(), store.clients(), store.consents(),
        store.consentWriter()).storeAcceptedScopes("acme", "alice", "web", List.of("openid"));
    store.db()
        .execute("INSERT INTO _oauth_session (session, user_uid, client_id, issuer,"
            + " auth_data, csid, ip_address, user_agent) VALUES ('s-1', '" + alice + "', 'web',"
            + " 'https://acme.test', '{\"uid\":\"" + alice + "\"}', 'c', '10.0.0.1', 'Firefox')");
    String terms = OidcRepositories.uid();
    store.db().execute("INSERT INTO identity_tenant_terms_of_use (uid, version, enabled, text,"
        + " tenant) VALUES ('" + terms + "', 1, true, 'Terms', '" + tenant + "')");
    store.db()
        .execute("INSERT INTO identity_user_accepted_terms_of_use (uid, version,"
            + " accept_date, ip_address, terms_of_use, user) VALUES ('" + OidcRepositories.uid()
            + "', 1, CURRENT_TIMESTAMP, '10.0.0.2', '" + terms + "', '" + alice + "')");
    store.db()
        .execute("INSERT INTO _oauth_audit_log (uid, tenant_id, event_type, user_id,"
            + " ip_address, created_at) VALUES ('" + OidcRepositories.uid() + "', '" + tenant
            + "', 'login', '" + alice + "', '10.0.0.3', CURRENT_TIMESTAMP)");

    JsonNode json = exported(alice);

    Assertions.assertEquals("acme", json.get("tenant").asText());
    Assertions.assertEquals(alice, json.get("profile").get("uid").asText());
    Assertions.assertEquals("alice@acme.test", json.get("profile").get("email").asText());
    Assertions.assertTrue(json.get("profile").get("enabled").asBoolean());
    Assertions.assertEquals("openid", json.get("grantedScopes").get(0).get("scope").asText());
    Assertions.assertEquals("s-1", json.get("sessions").get(0).get("sessionId").asText());
    Assertions.assertEquals("Firefox", json.get("sessions").get(0).get("userAgent").asText());
    Assertions.assertEquals(terms, json.get("acceptedTerms").get(0).get("termsUid").asText());
    Assertions.assertEquals("10.0.0.2", json.get("acceptedTerms").get(0).get("ipAddress").asText());
    Assertions.assertEquals("login", json.get("auditLog").get(0).get("eventType").asText());
  }

  @Test
  @DisplayName("An unknown user exports an empty profile")
  void unknown_user() throws Exception {
    JsonNode json = exported("missing");

    Assertions.assertTrue(json.get("profile").isEmpty());
    Assertions.assertTrue(json.get("grantedScopes").isEmpty());
    Assertions.assertTrue(json.get("sessions").isEmpty());
  }

  @Test
  @DisplayName("Only the sessions of the user are exported")
  void own_sessions() throws Exception {
    String bob = store.user(tenant, "bob", "bob@acme.test");
    for (String[] session : new String[][] {{"s-alice", alice}, {"s-bob", bob}}) {
      store.db()
          .execute("INSERT INTO _oauth_session (session, user_uid, client_id, issuer,"
              + " auth_data, csid) VALUES ('" + session[0] + "', '" + session[1] + "', 'web',"
              + " 'iss', '{\"uid\":\"" + session[1] + "\"}', 'c')");
    }

    JsonNode sessions = exported(alice).get("sessions");

    Assertions.assertEquals(1, sessions.size());
    Assertions.assertEquals("s-alice", sessions.get(0).get("sessionId").asText());
  }

  @Test
  @DisplayName("A failure on the mail does not reach the caller")
  void mail_failure() {
    Mockito.doThrow(new IllegalStateException("smtp down")).when(mail)
        .delaySendMessage(Mockito.any());

    Assertions
        .assertDoesNotThrow(() -> export.requestExport(alice, "alice", "alice@acme.test", "acme"));
  }
}
